head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71901";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71901.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지)"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_Search, tx_fn_DigitalMst) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71901.btn_Search_onclick' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.digitalMst(r["isuCd"], r["bzProcsNo"], r["listBzTpCd"], r["lastSaveStatCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name __on_enter_1_ipt_isunm
 * @description on enter 1 ipt isunm 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_isunm = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71901.__on_enter_1_ipt_isuNm' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_90_onclick
 * @description krxpage_pagenavigator_90 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_90_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_90.page' }); } await scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_DigitalMst
 * @description Digital Mst 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalMst = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalMst",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name digitalMst
 * @description digital Mst 처리
 * @param {String} isuCd isuCd
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzTpCd listBzTpCd
 * @param {*} tabNo tabNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalMst = async function (isuCd, bzProcsNo, listBzTpCd, tabNo) {
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'viewIsuTab');
    $c.util.getComponent('dma_SearchReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent("slc_listBzTpCd").setValue(listBzTpCd);
    $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', tabNo);
    await scwin.tx_fn_DigitalMst();
};
